.period-control button:hover { color: var(--accent); }
.period-control button.selected { color: var(--text); background: var(--surface); box-shadow: 0 1px 4px #0a352716; font-weight: 600; }
.pause-button { display: grid; place-items: center; border: 1px solid var(--border); border-radius: 5px; height: 33px; width: 33px; background: var(--surface); color: var(--secondary); }
.pause-button:hover { background: var(--soft); }
.is-paused { color: #b08c43; }
